from collections import deque


def transform(grid):
    """Color the one-cell inner edge and exterior halo of enclosed zero regions."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    enclosed_regions = []

    # Four-connected background components distinguish true closed cavities.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            touches_edge = False
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                if x == 0 or y == 0 or x == h - 1 or y == w - 1:
                    touches_edge = True
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if not touches_edge:
                enclosed_regions.append(set(cells))

    enclosed_cells = set().union(*enclosed_regions) if enclosed_regions else set()
    boundary_ones = set()
    for region in enclosed_regions:
        for r, c in region:
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                    boundary_ones.add((nr, nc))
                    out[r][c] = 3

    # The matching one-cell outer rim is the 8-neighbor halo of the contour.
    for r, c in boundary_ones:
        for nr in range(max(0, r - 1), min(h, r + 2)):
            for nc in range(max(0, c - 1), min(w, c + 2)):
                if grid[nr][nc] == 0 and (nr, nc) not in enclosed_cells:
                    out[nr][nc] = 2
    return out


