from collections import deque


def transform(grid):
    """Mark inner edge cells and exterior 8-neighbor halo for closed 1-components."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Identify four-connected zero regions that are enclosed by the 1-lines.
    zero_seen = set()
    enclosed_regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in zero_seen:
                continue
            q = deque([(r, c)])
            zero_seen.add((r, c))
            cells = set()
            touches_edge = False
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                if x == 0 or y == 0 or x == h - 1 or y == w - 1:
                    touches_edge = True
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in zero_seen:
                        zero_seen.add((nx, ny))
                        q.append((nx, ny))
            if not touches_edge:
                enclosed_regions.append(cells)

    if not enclosed_regions:
        return out

    # Components containing walls of an enclosed region are the selected objects.
    one_seen = set()
    selected_ones = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in one_seen:
                continue
            q = deque([(r, c)])
            one_seen.add((r, c))
            component = {(r, c)}
            while q:
                x, y = q.popleft()
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1 and (nx, ny) not in one_seen:
                        one_seen.add((nx, ny))
                        component.add((nx, ny))
                        q.append((nx, ny))
            if any(any((r0 + dr, c0 + dc) in component for r0, c0 in region for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1))) for region in enclosed_regions):
                selected_ones.update(component)

    enclosed_cells = set().union(*enclosed_regions)
    # Color only cavity cells directly touching a wall (not the deeper interior).
    for region in enclosed_regions:
        for r, c in region:
            if any(0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1
                   for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))):
                out[r][c] = 3

    # Paint a one-cell diagonal-inclusive halo around the entire selected outline.
    for r, c in selected_ones:
        for nr in range(max(0, r - 1), min(h, r + 2)):
            for nc in range(max(0, c - 1), min(w, c + 2)):
                if grid[nr][nc] == 0 and (nr, nc) not in enclosed_cells:
                    out[nr][nc] = 2
    return out


