from collections import deque


def transform(grid):
    """Color enclosed zero pockets and add a diagonal-inclusive outside rim."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    zero_seen = set()
    enclosed_regions = []

    # Use 8-connectivity for background: diagonal leaks count as openings.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in zero_seen:
                continue
            q = deque([(r, c)])
            zero_seen.add((r, c))
            region = set()
            touches_edge = False
            while q:
                x, y = q.popleft()
                region.add((x, y))
                touches_edge |= x == 0 or y == 0 or x == h - 1 or y == w - 1
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        if dx == dy == 0:
                            continue
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in zero_seen:
                            zero_seen.add((nx, ny))
                            q.append((nx, ny))
            if not touches_edge:
                enclosed_regions.append(region)

    if not enclosed_regions:
        return out

    enclosed_cells = set().union(*enclosed_regions)
    # Any 1-component forming the boundary of an enclosed pocket is selected.
    seen = set()
    selected_ones = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = {(r, c)}
            while q:
                x, y = q.popleft()
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        component.add((nx, ny))
                        q.append((nx, ny))
            if any(any((x + dx, y + dy) in component for x, y in region for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1))) for region in enclosed_regions):
                selected_ones.update(component)

    # Color the cavity layer adjacent to its 1-boundary; deeper cells stay 0.
    for region in enclosed_regions:
        for r, c in region:
            if any(0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1
                   for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))):
                out[r][c] = 3

    # The outside marking is a one-cell Moore-neighborhood rim of the contour.
    for r, c in selected_ones:
        for nr in range(max(0, r - 1), min(h, r + 2)):
            for nc in range(max(0, c - 1), min(w, c + 2)):
                if grid[nr][nc] == 0 and (nr, nc) not in enclosed_cells:
                    out[nr][nc] = 2
    return out


