from collections import deque


def transform(grid):
    """Trace a one-cell rectangular frame around each fully closed 1-object."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    regions = []
    # 4-neighbor zero components: enclosed components identify closed outlines.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            edge = False
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                edge |= x in (0, h - 1) or y in (0, w - 1)
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if not edge:
                regions.append(cells)
    if not regions:
        return out

    # Each cavity associates to the connected 1-object that surrounds it.
    one_seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in one_seen:
                continue
            q = deque([(r, c)])
            one_seen.add((r, c))
            obj = {(r, c)}
            while q:
                x, y = q.popleft()
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1 and (nx, ny) not in one_seen:
                        one_seen.add((nx, ny))
                        obj.add((nx, ny))
                        q.append((nx, ny))
            objects.append(obj)

    for region in regions:
        # Identify the wall cells bordering this pocket, then recover its object.
        wall = set()
        for r, c in region:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if (dr or dc) and 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                        wall.add((nr, nc))
        obj = next((o for o in objects if o & wall), set())
        if not obj:
            continue
        rmin, rmax = min(r for r, _ in obj), max(r for r, _ in obj)
        cmin, cmax = min(c for _, c in obj), max(c for _, c in obj)
        enclosed_cells = set().union(*regions)

        # Interior: 3 on the one-cell layer touching the wall, deeper cavity stays 0.
        for r, c in region:
            if any((r + dr, c + dc) in obj for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc):
                out[r][c] = 3

        # Exterior: rectangular frame immediately outside the object's bounding box.
        top, bottom = max(0, rmin - 1), min(h - 1, rmax + 1)
        left, right = max(0, cmin - 1), min(w - 1, cmax + 1)
        for c in range(left, right + 1):
            for r in (top, bottom):
                if grid[r][c] == 0 and (r, c) not in enclosed_cells:
                    out[r][c] = 2
        for r in range(top, bottom + 1):
            for c in (left, right):
                if grid[r][c] == 0 and (r, c) not in enclosed_cells:
                    out[r][c] = 2
    return out


