from collections import deque


def transform(grid):
    """For closed 1-line objects, color their inner edge 3 and outer halo 2."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find 4-connected zero components that do not reach the canvas boundary.
    zero_seen = set()
    cavities = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in zero_seen:
                continue
            q = deque([(r, c)])
            zero_seen.add((r, c))
            cells = set()
            touches_edge = False
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                touches_edge |= x in (0, h - 1) or y in (0, w - 1)
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in zero_seen:
                        zero_seen.add((nx, ny))
                        q.append((nx, ny))
            if not touches_edge:
                cavities.append(cells)

    if not cavities:
        return out

    # Label all orthogonally connected 1-objects.
    one_seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in one_seen:
                continue
            q = deque([(r, c)])
            one_seen.add((r, c))
            obj = {(r, c)}
            while q:
                x, y = q.popleft()
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1 and (nx, ny) not in one_seen:
                        one_seen.add((nx, ny))
                        obj.add((nx, ny))
                        q.append((nx, ny))
            objects.append(obj)

    for cavity in cavities:
        # Associate cavity with its 1-wall via direct orthogonal adjacency.
        wall = {(r + dr, c + dc) for r, c in cavity for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1))
                if 0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == 1}
        obj = next((o for o in objects if o & wall), None)
        if obj is None:
            continue

        # Mark the inner cavity layer (8-neighbor to the closed 1-wall) in 3.
        for r, c in cavity:
            if any((r + dr, c + dc) in obj for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc):
                out[r][c] = 3

        # Mark the one-cell Moore-neighborhood outside this closed object in 2.
        for r, c in obj:
            for nr in range(max(0, r - 1), min(h, r + 2)):
                for nc in range(max(0, c - 1), min(w, c + 2)):
                    if grid[nr][nc] == 0 and (nr, nc) not in cavity:
                        out[nr][nc] = 2
    return out


if __name__ == "__main__":
    pass

