from collections import deque


def transform(grid):
    """Mark enclosed zero cavities: bounding-box inner edge 3, outer frame 2."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    cavities = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            region = set()
            touches_edge = False
            while q:
                x, y = q.popleft()
                region.add((x, y))
                touches_edge |= x == 0 or y == 0 or x == h - 1 or y == w - 1
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if not touches_edge:
                cavities.append(region)

    all_cavities = set().union(*cavities) if cavities else set()
    for region in cavities:
        # Only closed contours are transformed: require a 1-cell on all four sides.
        r0, r1 = min(r for r, _ in region), max(r for r, _ in region)
        c0, c1 = min(c for _, c in region), max(c for _, c in region)
        if not (r0 > 0 and c0 > 0 and r1 < h - 1 and c1 < w - 1):
            continue
        if not (all(grid[r0 - 1][c] == 1 for c in range(c0 - 1, c1 + 2)) and
                all(grid[r1 + 1][c] == 1 for c in range(c0 - 1, c1 + 2)) and
                all(grid[r][c0 - 1] == 1 and grid[r][c1 + 1] == 1 for r in range(r0 - 1, r1 + 2))):
            # Irregular closed lines can be partially ragged; use presence on each side.
            top = any(grid[r0 - 1][c] == 1 for c in range(c0, c1 + 1))
            bottom = any(grid[r1 + 1][c] == 1 for c in range(c0, c1 + 1))
            left = any(grid[r][c0 - 1] == 1 for r in range(r0, r1 + 1))
            right = any(grid[r][c1 + 1] == 1 for r in range(r0, r1 + 1))
            if not (top and bottom and left and right):
                continue

        # Fill a one-cell-thick rim just inside the cavity's bounding box.
        for r, c in region:
            if r in (r0, r1) or c in (c0, c1):
                out[r][c] = 3

        # Draw a one-cell-thick rectangular frame just outside the contour bbox.
        for c in range(max(0, c0 - 2), min(w, c1 + 3)):
            for r in (r0 - 2, r1 + 2):
                if 0 <= r < h and grid[r][c] == 0 and (r, c) not in all_cavities:
                    out[r][c] = 2
        for r in range(max(0, r0 - 2), min(h, r1 + 3)):
            for c in (c0 - 2, c1 + 2):
                if 0 <= c < w and grid[r][c] == 0 and (r, c) not in all_cavities:
                    out[r][c] = 2
    return out


