def transform(grid):
    """Extend the middle row and column of every solid 3x3 colored block."""
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                center = (r + 1, c + 1, color)
                if center not in centers:
                    centers.append(center)

    out = [row[:] for row in grid]
    rays = {}
    for r, c, color in centers:
        for cc in range(w):
            rays.setdefault((r, cc), set()).add(color)
        for rr in range(h):
            rays.setdefault((rr, c), set()).add(color)

    for (r, c), colors in rays.items():
        if len(colors) > 1:
            out[r][c] = 0
        elif out[r][c] == 0:
            out[r][c] = next(iter(colors))
    return out

