def transform(grid):
    """Return a panel-sized grid filled with the color shared by both panels."""
    h, w = len(grid), len(grid[0])
    # A one-cell-thick uniform line divides the two panels.
    for r in range(h):
        if len(set(grid[r])) == 1:
            a, b = grid[:r], grid[r + 1:]
            if a and b and len(a[0]) == len(b[0]):
                shared = set(x for row in a for x in row) & set(x for row in b for x in row)
                if len(shared) == 1:
                    return [[next(iter(shared)) for _ in range(w)] for _ in range(h - 1)]
    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid):
            a = [row[:c] for row in grid]
            b = [row[c + 1:] for row in grid]
            if a[0] and b[0] and len(a[0]) == len(b[0]):
                shared = set(x for row in a for x in row) & set(x for row in b for x in row)
                if len(shared) == 1:
                    return [[next(iter(shared)) for _ in range(w - 1)] for _ in range(h)]
    raise ValueError("No single-color shared by two equal-sized panels found")


