def transform(grid):
    """Bridge same-color horizontal gaps and extend all resulting/guide lines upward."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    sources = []
    bar_rows = []

    # Complete only dense horizontal bars, bridging a gap when its nearest
    # colored cells to the left and right agree.
    for r, row in enumerate(grid):
        if sum(v != 0 for v in row) < 5:
            continue
        bar_rows.append(r)
        cols = [c for c, value in enumerate(row) if value]
        for c in range(min(cols), max(cols) + 1):
            if row[c] != 0:
                continue
            left = next((row[j] for j in range(c - 1, -1, -1) if row[j]), None)
            right = next((row[j] for j in range(c + 1, w) if row[j]), None)
            if left is not None and left == right:
                out[r][c] = left
                sources.append((r, c, left))

    # Newly completed gaps project upward. Existing colored cells stop rays.
    for r, c, color in sources:
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color

    # Sparse vertical guide objects lie below the horizontal bars and likewise
    # project upward, stopping at the first filled/occupied cell.
    if bar_rows:
        lower_start = max(bar_rows) + 1
        for c in range(w):
            guides = [(r, grid[r][c]) for r in range(lower_start, h) if grid[r][c] != 0]
            if not guides:
                continue
            r0, color = min(guides)
            for rr in range(r0 - 1, -1, -1):
                if out[rr][c] != 0:
                    break
                out[rr][c] = color
    return out

