def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    edge_runs = []
    for r, dr in ((0, 1), (h - 1, -1)):
        c = 0
        while c < w:
            color = grid[r][c]
            end = c + 1
            while end < w and grid[r][end] == color:
                end += 1
            if color != bg and end - c >= 2:
                edge_runs.append((r, dr, c, end - 1))
            c = end
    non_bg = [v for row in grid for v in row if v != bg]
    bar_colors = {grid[r][c] for r, _, a, b in edge_runs for c in range(a, b + 1)}
    ray_colors = [v for v in non_bg if v not in bar_colors]
    ray_color = ray_colors[0] if ray_colors else next(iter(bar_colors))
    for r, dr, a, b in edge_runs:
        for c in {a, b}:
            rr = r + dr
            while 0 <= rr < h:
                if grid[rr][c] not in (bg, ray_color):
                    break
                if grid[rr][c] == ray_color:
                    out[rr][c] = 4
                    break
                out[rr][c] = ray_color
                rr += dr
    return out

