            # Fallback: pick the period explaining the greatest number of
            # visible cells, with the shorter period breaking ties.
            best = None
            for p in range(2, min(12, w + 1)):
                bins = {}
                for c, value in known:
                    bins.setdefault(c % p, {}).setdefault(value, 0)
                    bins[c % p][value] += 1
                score = sum(max(v.values()) for v in bins.values())
