A demonstrated pattern: an abundant background (0) surrounds a closed wall (3); only the 2×2 background cavity changes to fill color 4, while the exterior and wall remain unchanged. A reusable candidate transform marks background reachable from any grid edge using 4-neighbor flood fill, then recolors unreached background cells.

```python
from collections import Counter, deque

def fill_enclosed(grid, fill_color):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    exterior, q = set(), deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == bg and (r, c) not in exterior:
                exterior.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == bg and (r, c) not in exterior:
                exterior.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr,nc) not in exterior:
                exterior.add((nr,nc)); q.append((nr,nc))
    return [[fill_color if grid[r][c] == bg and (r,c) not in exterior else grid[r][c]
             for c in range(w)] for r in range(h)]
